-- FMP-shaped SOURCE schema for the dry run (synthetic data only). Columns follow apps/funnel-mapper/supabase/migrations (as of the pristine copy).
create schema fmp_src;
create table fmp_src.workspaces (id uuid primary key, kind text not null check (kind in ('team', 'personal')), agency_name text not null, agency_logo_url text, default_currency text not null default 'GBP', created_at timestamptz not null default now());
create table fmp_src.profiles (id uuid primary key, email text not null, full_name text, workspace_id uuid references fmp_src.workspaces(id));
create table fmp_src.workspace_members (workspace_id uuid not null references fmp_src.workspaces(id), user_id uuid not null references fmp_src.profiles(id), role text not null check (role in ('owner', 'admin', 'editor', 'viewer')), active boolean not null default true, primary key (workspace_id, user_id));
create table fmp_src.clients (id uuid primary key, workspace_id uuid not null references fmp_src.workspaces(id), name text not null, business_name text not null default '', niche text not null default '', email text not null default '', phone text not null default '', website text not null default '', country text not null default '', currency text not null default 'GBP', logo_url text,
  status text not null default 'lead' check (status in ('lead', 'proposal', 'active', 'paused', 'past')), monthly_retainer numeric(12, 2) not null default 0, pricing_model text not null default 'retainer', pricing_amount numeric(12, 2) not null default 0, notes text not null default '', tags text[] not null default '{}',
  archived_at timestamptz, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table fmp_src.products (id uuid primary key, workspace_id uuid not null references fmp_src.workspaces(id), client_id uuid references fmp_src.clients(id), name text not null, type text not null default 'product', params jsonb not null default '{}', notes text not null default '', created_at timestamptz not null default now());
create table fmp_src.funnels (id uuid primary key, workspace_id uuid not null references fmp_src.workspaces(id), client_id uuid not null references fmp_src.clients(id), name text not null, description text not null default '', status text not null default 'draft' check (status in ('draft', 'proposed', 'live', 'archived')),
  graph jsonb not null, settings jsonb not null default '{}', summary jsonb not null default '{}', thumbnail_url text, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table fmp_src.funnel_versions (id uuid primary key, workspace_id uuid not null, funnel_id uuid not null references fmp_src.funnels(id), graph jsonb not null, settings jsonb not null, label text not null default '', auto boolean not null default false, created_at timestamptz not null default now());
create table fmp_src.funnel_actuals (id uuid primary key, workspace_id uuid not null, funnel_id uuid not null references fmp_src.funnels(id), period_start date not null, period_end date not null, node_id text not null, visitors numeric, conversions numeric, revenue numeric, spend numeric, source text not null default 'manual', unique (funnel_id, period_start, period_end, node_id));
create table fmp_src.share_links (id uuid primary key, workspace_id uuid not null, funnel_id uuid not null references fmp_src.funnels(id), token text not null unique, can_edit boolean not null default false, hide_numbers boolean not null default false, allow_comments boolean not null default true, expires_at timestamptz, created_at timestamptz not null default now());
create table fmp_src.share_comments (id uuid primary key, workspace_id uuid not null, share_link_id uuid not null references fmp_src.share_links(id), funnel_id uuid not null references fmp_src.funnels(id), node_id text, author_name text not null default '', body text not null, resolved boolean not null default false, created_at timestamptz not null default now());
create table fmp_src.templates (id uuid primary key, workspace_id uuid, builtin_key text unique, name text not null, category text not null default 'Custom', description text not null default '', graph jsonb not null, settings jsonb not null default '{}');
